do $m$ declare src text;anchor text:=$a$new.datos->>'clase_expediente'='anuncio' then$a$;replacement text:=$a$new.datos->>'clase_expediente'='anuncio' and exists(select 1 from public.gob_registros e join public.gob_registros p on p.id::text=e.datos->>'presidenciaId' where e.id::text=new.datos->>'expediente' and e.tipo='secretaria' and p.tipo='peticion' and p.estado in ('autorizada','condicionada','en_curso','cumplida')) then$a$;begin src:=pg_get_functiondef('public.gob_encolar_difusion()'::regprocedure);if position(anchor in src)=0 then raise exception 'PROGRAMA_NO_LOCALIZADO';end if;execute replace(src,anchor,replacement);end $m$;
